contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        uint balAfterDeposit = address(c).balance;
        c.withdrawAll();
        uint balAfterSelfWithdraw = address(c).balance;
        // self withdraw restored balance
        assert(balAfterSelfWithdraw == balAfterDeposit - amount);
        // simulate second account via receiving ether and depositing? only msg.sender is this contract, so instead rule: credit reset means second withdrawAll sends nothing
        uint before2 = address(this).balance;
        c.withdrawAll();
        assert(address(this).balance == before2 && address(c).balance == balAfterSelfWithdraw);
    }
    receive() external payable {}
}

