    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        if (amount > 0) {
            c.deposit{value: amount}();
            c.withdrawAll();
        }
        uint cBefore = address(c).balance;
        uint meBefore = address(this).balance;
        uint creditBefore = c.credit(address(this));
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(c).balance == cBefore && address(this).balance == meBefore && c.credit(address(this)) == creditBefore);
    }
    receive() external payable {}
}

