        c.deposit{value: amount}();
        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        bool outerReverted;
        try c.withdrawAll() { outerReverted = false; } catch { outerReverted = true; }
        assert(
            innerCallAttempted &&
            innerCallReverted &&
            !outerReverted &&
            address(this).balance >= balBefore &&
            address(c).balance == cBalBefore - amount
        );
    }

    receive() external payable {
        innerCallAttempted = true;
        try c.withdrawAll() { innerCallReverted = false; } catch { innerCallReverted = true; }
    }
}

contract InvMutTest {
    C c;
    bool reDepositing;
    uint reDepositAmount;

    constructor(C _c) { c = _c; }

    function run(uint amount, uint extra) public payable {
        require(amount > 0);
        require(address(this).balance >= amount + extra);
        c.deposit{value: amount}();
        uint cBal0 = address(c).balance;
        reDepositAmount = extra;
        reDepositing = true;
        bool outerReverted;
        try c.withdrawAll() { outerReverted = false; } catch { outerReverted = true; }
        reDepositing = false;
        require(!outerReverted);
        uint balAfterFirst = address(this).balance;
        bool secondReverted;
        try c.withdrawAll() { secondReverted = false; } catch { secondReverted = true; }
        assert(
            !secondReverted &&
            address(this).balance == balAfterFirst + extra &&
            address(c).balance == cBal0
        );
    }

    receive() external payable {
        if (reDepositing) {
            c.deposit{value: reDepositAmount}();
            reDepositing = false;
        }
    }
}

